B.aa1=new A.p(B.h,["You have 14 days from the date of purchase to exchange or receive a full refund.","\u0644\u062f\u064a\u0643 14 \u064a\u0648\u0645\u0627\u064b \u0645\u0646 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0634\u0631\u0627\u0621 \u0644\u0644\u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0623\u0648 \u0627\u0633\u062a\u0631\u062c\u0627\u0639 \u0627\u0644\u0645\u0628\u0644\u063a \u0643\u0627\u0645\u0644\u0627\u064b."],t.w)
B.a8T=new A.p(B.h,["Items must be unused and in their original condition, with labels, tags and instructions still attached.","\u064a\u062c\u0628 \u0623\u0646 \u062a\u0643\u0648\u0646 \u0627\u0644\u0642\u0637\u0639 \u063a\u064a\u0631 \u0645\u0633\u062a\u0639\u0645\u0644\u0629 \u0648\u0628\u062d\u0627\u0644\u062a\u0647\u0627 \u0627\u0644\u0623\u0635\u0644\u064a\u0629\u060c \u0645\u0639 \u0628\u0642\u0627\u0621 \u0627\u0644\u0645\u0644\u0635\u0642\u0627\u062a \u0648\u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062a \u0648\u0627\u0644\u062a\u0639\u0644\u064a\u0645\u0627\u062a \u0643\u0645\u0627 \u0647\u064a."],t.w)
B.a92=new A.p(B.h,["Bring the purchase invoice with you.","\u0623\u062d\u0636\u0631\u064a \u0641\u0627\u062a\u0648\u0631\u0629 \u0627\u0644\u0634\u0631\u0627\u0621."],t.w)
B.a8P=new A.p(B.h,["Underwear and lingerie (bras and panties) cannot be exchanged or refunded.","\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0633\u062a\u0628\u062f\u0627\u0644 \u0623\u0648 \u0627\u0633\u062a\u0631\u062c\u0627\u0639 \u0627\u0644\u0645\u0644\u0627\u0628\u0633 \u0627\u0644\u062f\u0627\u062e\u0644\u064a\u0629 (\u0627\u0644\u062d\u0645\u0627\u0644\u0627\u062a \u0648\u0627\u0644\u0643\u064a\u0644\u0648\u062a\u0627\u062a)."],t.w)
B.a8u=new A.p(B.h,["Returns are accepted only at the brand's stores in the major malls across Kuwait.","\u062a\u064f\u0642\u0628\u0644 \u0627\u0644\u0645\u0631\u062a\u062c\u0639\u0627\u062a \u0641\u0642\u0637 \u0641\u064a \u0641\u0631\u0648\u0639 \u0627\u0644\u0645\u0627\u0631\u0643\u0629 \u062f\u0627\u062e\u0644 \u0627\u0644\u0645\u062c\u0645\u0639\u0627\u062a \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u0629 \u0641\u064a \u0627\u0644\u0643\u0648\u064a\u062a."],t.w)
B.a83=new A.p(B.h,["Refunds go back to the payment method you used. Cash refunds are given in person at the store. Card refunds can take up to 7 working days to reach your account.","\u064a\u0639\u0648\u062f \u0627\u0644\u0645\u0628\u0644\u063a \u0628\u0646\u0641\u0633 \u0637\u0631\u064a\u0642\u0629 \u0627\u0644\u062f\u0641\u0639. \u0627\u0644\u0627\u0633\u062a\u0631\u062c\u0627\u0639 \u0627\u0644\u0646\u0642\u062f\u064a \u064a\u062a\u0645 \u0634\u062e\u0635\u064a\u0627\u064b \u0641\u064a \u0627\u0644\u0641\u0631\u0639. \u0648\u0642\u062f \u064a\u0633\u062a\u063a\u0631\u0642 \u0627\u0644\u0627\u0633\u062a\u0631\u062c\u0627\u0639 \u0639\u0644\u0649 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u062d\u062a\u0649 7 \u0623\u064a\u0627\u0645 \u0639\u0645\u0644."],t.w)
